+import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
+
+import {
+  addFavorite,
+  getFavorites,
+  isFavorite,
+  removeFavorite,
+} from '@/services/favorites-db';
+import type { Pokemon } from '@/services/pokemon';
+
+export function useFavorites() {
+  return useQuery({
+    queryKey: ['favorites'],
+    queryFn: getFavorites,
+  });
+}
+
+export function useIsFavorite(id: number) {
+  return useQuery({
+    queryKey: ['favorites', id],
+    queryFn: () => isFavorite(id),
+    enabled: id > 0,
+  });
+}
+
+export function useAddFavorite() {
+  const queryClient = useQueryClient();
+
+  return useMutation({
+    mutationFn: (pokemon: Pokemon) => addFavorite(pokemon),
+    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['favorites'] }),
+  });
+}
+
+export function useRemoveFavorite() {
+  const queryClient = useQueryClient();
+
+  return useMutation({
+    mutationFn: (id: number) => removeFavorite(id),
+    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['favorites'] }),
+  });
+}
*** End Patch","explanation":"Add favorites list, per-ID lookup, and mutation hooks with shared invalidation"}

